package ru.homebooks.library;

import android.content.Intent;
import android.graphics.*;
import android.os.Bundle;
import android.text.TextUtils;
import android.view.*;
import android.widget.*;
import androidx.activity.ComponentActivity;
import java.util.*;

public final class SeriesDetailActivity extends ComponentActivity {
    private LibraryApp app;private long id;private LinearLayout root;private int request;
    @Override public void onCreate(Bundle state){super.onCreate(state);app=(LibraryApp)getApplication();id=getIntent().getLongExtra("seriesId",-1);}
    @Override protected void onResume(){super.onResume();load();}
    private void load(){int token=++request;app.io.execute(()->{try{BookSeries series=app.store.bookSeries(id);Map<String,Book> books=new HashMap<>();for(Book book:app.store.all())books.put(book.id,book);runOnUiThread(()->{if(isDestroyed()||token!=request)return;if(series==null){finish();return;}render(series,books);});}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"Не удалось открыть серию",Toast.LENGTH_LONG).show());}});}
    private void render(BookSeries series,Map<String,Book> books){root=Ui.column(this);root.setBackgroundColor(Ui.PAPER);setContentView(root);Ui.insets(root);LinearLayout toolbar=Ui.toolbar(this,series.kind==BookSeries.BOOKS?"Серия":"Журнал",this::finish);Button edit=Ui.editButton(this,"Редактировать «"+series.name+"»",()->startActivity(new Intent(this,SeriesEditorActivity.class).putExtra("seriesId",series.id)));toolbar.addView(edit);root.addView(toolbar);
        ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout body=Ui.column(this);body.setPadding(Ui.dp(this,16),Ui.dp(this,8),Ui.dp(this,16),Ui.dp(this,28));scroll.addView(body);body.addView(Ui.eyebrow(this,series.kindLabel().toUpperCase(new Locale("ru"))));Ui.gap(body,6);TextView title=Ui.heading(this,series.name);title.setTextSize(28);body.addView(title);Ui.gap(body,6);body.addView(Ui.muted(this,summary(series),14));
        if(series.kind==BookSeries.BOOKS&&series.totalParts!=null){String missing=missing(series);if(!missing.isEmpty()){Ui.gap(body,14);LinearLayout note=Ui.column(this);note.setPadding(Ui.dp(this,14),Ui.dp(this,12),Ui.dp(this,14),Ui.dp(this,12));note.setBackground(Ui.round(Ui.TINT,this));note.addView(Ui.text(this,"Не хватает: "+missing,14));body.addView(note);}}
        Ui.gap(body,22);List<BookSeries.Member> members=new ArrayList<>(series.members);Collections.sort(members,(a,b)->compare(series,a,b));String year="";for(BookSeries.Member member:members){Book book=books.get(member.bookId);if(book==null)continue;if(series.kind==BookSeries.PERIODICAL){String next=member.issueDate.length()>=4?member.issueDate.substring(0,4):"Дата не указана";if(!next.equals(year)){year=next;TextView heading=Ui.text(this,year,20);heading.setTypeface(Typeface.create("serif",Typeface.NORMAL));heading.setTextColor(Ui.GREEN);heading.setPadding(0,Ui.dp(this,12),0,Ui.dp(this,4));body.addView(heading);}}
            body.addView(bookRow(series,member,book));Ui.divider(body);}
        if(series.members.isEmpty()){TextView empty=Ui.muted(this,series.kind==BookSeries.BOOKS?"Книг пока нет":"Выпусков пока нет",15);empty.setGravity(Gravity.CENTER);body.addView(empty,new LinearLayout.LayoutParams(-1,Ui.dp(this,180)));}}
    private View bookRow(BookSeries series,BookSeries.Member member,Book book){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(0,Ui.dp(this,10),0,Ui.dp(this,10));row.setMinimumHeight(Ui.dp(this,72));row.setOnClickListener(v->startActivity(new Intent(this,AddBookActivity.class).putExtra("isbn",book.id)));row.setBackground(new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(0x14735081),Ui.round(Color.TRANSPARENT,this),null));ImageView cover=new ImageView(this);cover.setImageDrawable(new Ui.Symbol("book",Ui.GREEN));cover.setBackground(Ui.surface(this,Ui.TINT,Ui.LINE,4));Ui.pad(cover,8);row.addView(cover,new LinearLayout.LayoutParams(Ui.dp(this,44),Ui.dp(this,62)));LinearLayout words=Ui.column(this);words.setPadding(Ui.dp(this,12),0,0,0);TextView title=Ui.text(this,book.title,15);title.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));title.setMaxLines(2);title.setEllipsize(TextUtils.TruncateAt.END);words.addView(title);String detail=series.kind==BookSeries.PERIODICAL?BookSeries.memberLabel(series,member):member.position.isEmpty()?"Номер части не указан":"Книга "+member.position;words.addView(Ui.muted(this,detail,13));row.addView(words,new LinearLayout.LayoutParams(0,-2,1));ImageView arrow=new ImageView(this);arrow.setImageDrawable(new Ui.Symbol("forward",Ui.MUTED));row.addView(arrow,new LinearLayout.LayoutParams(Ui.dp(this,18),Ui.dp(this,18)));return row;}
    private String summary(BookSeries series){if(series.kind==BookSeries.PERIODICAL)return series.members.size()+" "+word(series.members.size(),"выпуск","выпуска","выпусков");return series.totalParts==null?series.members.size()+" "+word(series.members.size(),"книга","книги","книг"):series.members.size()+" из "+series.totalParts+" книг";}
    private String word(int n,String one,String few,String many){int a=n%100,b=a%10;return a>10&&a<20?many:b==1?one:b>=2&&b<=4?few:many;}
    private String missing(BookSeries series){Set<Integer> have=new HashSet<>();for(BookSeries.Member m:series.members)try{have.add(Integer.parseInt(m.position));}catch(Exception ignored){}List<String> values=new ArrayList<>();int total=0;for(int i=1;i<=series.totalParts;i++)if(!have.contains(i)){total++;if(values.size()<20)values.add(Integer.toString(i));}String result=join(values);return total>values.size()?result+" и ещё "+(total-values.size()):result;}
    private String join(List<String> values){if(values.isEmpty())return "";if(values.size()==1)return values.get(0);String result="";for(int i=0;i<values.size()-1;i++)result+=(i==0?"":", ")+values.get(i);return result+" и "+values.get(values.size()-1);}
    private int compare(BookSeries series,BookSeries.Member a,BookSeries.Member b){if(series.kind==BookSeries.PERIODICAL){int date=b.issueDate.compareTo(a.issueDate);if(date!=0)return date;return natural(a.issueNumber,b.issueNumber);}return natural(a.position,b.position);}
    private int natural(String a,String b){if(a.isEmpty())return b.isEmpty()?0:1;if(b.isEmpty())return -1;try{return Integer.compare(Integer.parseInt(a.replaceAll("[^0-9]","")),Integer.parseInt(b.replaceAll("[^0-9]","")));}catch(Exception e){return a.compareToIgnoreCase(b);}}
}
